actions.old_string:
def _convert_target_to_string(t: Any) -> Any:
    if isinstance(t, type):
        return f"{t.__module__}.{t.__name__}"
    elif callable(t):
        return f"{t.__module__}.{t.__qualname__}"
    else:
        return t

actions.new_string:
def _convert_target_to_string(t: Any) -> Any:
    if isinstance(t, type):
        # For nested classes, use __qualname__ which includes the outer class name
        if "." in t.__qualname__:
            return f"{t.__module__}.{t.__qualname__}"
        else:
            return f"{t.__module__}.{t.__name__}"
    elif callable(t):
        return f"{t.__module__}.{t.__qualname__}"
    else:
        return t
